package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("price_freezes") public class PriceFreeze{public enum Status{ACTIVE,EXPIRED,USED,CANCELLED}@Id private String id;@Indexed private String bookingId;@Indexed private String userId;private double frozenPrice;private Instant createdAt=Instant.now();@Indexed private Instant expiresAt;private Status status=Status.ACTIVE;public String getId(){return id;}public String getBookingId(){return bookingId;}public void setBookingId(String x){bookingId=x;}public String getUserId(){return userId;}public void setUserId(String x){userId=x;}public double getFrozenPrice(){return frozenPrice;}public void setFrozenPrice(double x){frozenPrice=x;}public Instant getCreatedAt(){return createdAt;}public Instant getExpiresAt(){return expiresAt;}public void setExpiresAt(Instant x){expiresAt=x;}public Status getStatus(){return status;}public void setStatus(Status x){status=x;}}
